import { evolu } from "./evolu/evolu_instance";
import { type AllSettingsQueryEntry, getSettingsQuery } from "./evolu/queries";
import { type SettingId, type InsertableSetting } from "$lib/database/evolu/datastructure";
import { queryState } from "$lib/database/nodeRepository.svelte";

export interface SettingDbEntryConfig {
  key: string;
  value: any;
}

export function mapToSettingDbEntry (dbResult: AllSettingsQueryEntry) {
  return {
    id: dbResult.id,
    key: dbResult.key,
    value: JSON.parse(dbResult.value ?? "{}")
  } as SettingDbEntryConfig;
}

export const SettingsRepository = {
  addSetting (setting: SettingDbEntryConfig): void {
    const newSetting: InsertableSetting = {
      ...setting
    };
    evolu.insert("settings", newSetting);
  },

  updateSetting (settingId: SettingId, setting: SettingDbEntryConfig): void {
    evolu.update("settings", {
      id: settingId,
        ...setting
    });
  },

  async getAllSettingsAsync (): Promise<SettingDbEntryConfig[]> {
    const query = getSettingsQuery();
    const rows = await evolu.loadQuery(query);
    return rows.map(mapToSettingDbEntry);
  },

  getAllSettingsState () {
    return queryState(() => getSettingsQuery(), evolu, {
      useLoadQueryResult: true
    });
  },

  async getSettingByKey (byKey: string): Promise<SettingDbEntryConfig> {
    const query = getSettingsQuery({
      byKey
    });
    const rows = await evolu.loadQuery(query);
    return rows.map(mapToSettingDbEntry)[0];
  },

  async getSetting (settingId: SettingId): Promise<SettingDbEntryConfig> {
    const query = getSettingsQuery({
      id: settingId
    });
    const rows = await evolu.loadQuery(query);

    return rows.map(mapToSettingDbEntry)[0];
  },

  deleteSetting (settingId: string): void {
    evolu.update("settings", { id: settingId, isDeleted: true });
  }
};
